SELECT 
FROM dms_shop_product_review

    AND product_id = #{productId}
    AND rating = #{rating}
    AND status = #{status}

        AND (product_name LIKE CONCAT('%', #{keyword}, '%')
          OR order_no LIKE CONCAT('%', #{keyword}, '%')
          OR reviewer_name LIKE CONCAT('%', #{keyword}, '%')
          OR content LIKE CONCAT('%', #{keyword}, '%'))


ORDER BY create_time DESC, id DESC

SELECT COUNT(*)
FROM dms_shop_order_item oi
INNER JOIN dms_shop_order o ON o.id = oi.order_id
LEFT JOIN dms_shop_product_review r ON r.order_item_id = oi.id
WHERE o.user_id = #{userId}
  AND o.id = #{orderId}
  AND o.status = 3
  AND o.tenant_id = #{tenantId}
  AND r.id IS NULL

mapper.update:
UPDATE dms_shop_product_review SET status = #{status},
hidden_reason = #{hiddenReason}, hidden_by = #{hiddenBy}, hidden_by_name = #{hiddenByName}, hidden_time = #{hiddenTime},
update_time = CURRENT_TIMESTAMP WHERE id = #{id}
